    // BOTÃO CALCULAR
    private void btnCalcularActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCalcularActionPerformed
        double valorPagar;
        
        // Pega o valor do campo txtPrecoUnitario
        double precoUnitario = Double.parseDouble(txtPrecoUnitario.getText());
        // Pega o valor do campo txtQtdeVendida
        int qtdeVendida = Integer.parseInt(txtQtdeVendida.getText());      
        
        valorPagar = precoUnitario * qtdeVendida;
        
        lblValorCompra.setText(String.valueOf(valorPagar));
        // Poderia ser feito da seguinte forma também:
        // lblValorCompra.setText(Double.toString(valorPagar));        
    }//GEN-LAST:event_btnCalcularActionPerformed

    // BOTÃO LIMPAR
    private void btnLimparActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLimparActionPerformed
        txtCodigo.setText("");
        txtNome.setText("");
        txtPrecoUnitario.setText("");
        txtQtdeVendida.setText("");
        lblValorCompra.setText("");
        txtCodigo.requestFocus();
    }//GEN-LAST:event_btnLimparActionPerformed

